"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[51846],{40140(a,n,i){i.r(n),i.d(n,{assets:()=>o,contentTitle:()=>l,default:()=>e,frontMatter:()=>m,metadata:()=>g,toc:()=>r});const g=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"Isang panimula sa kurso tungkol sa mga praktikal na aplikasyon ng quantum computing.","source":"@site/i18n/tl/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"Isang panimula sa kurso tungkol sa mga praktikal na aplikasyon ng quantum computing.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Praktikal na near-term na quantum computing","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"Pangkalahatang-tanaw","permalink":"/learning/courses/quantum-business-foundations/"}}');var t=i(74848),s=i(28453);const m={description:"Isang panimula sa kurso tungkol sa mga praktikal na aplikasyon ng quantum computing.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},l="Panimula sa praktikal na near-term quantum computing {#introduction-to-practical-near-term-quantum-computing}",o={},r=[{value:"Kung saan maaaring maging kapaki-pakinabang ang mga quantum computer",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Near-term na quantum utility at advantage",id:"near-term-quantum-utility-and-advantage",level:2},{value:"Maikling pundasyon sa complexity theory",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"Mula sa complexity theory tungo sa praktikal na ebidensya",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"Mga larangan ng aplikasyon at mga case study ng kurso",id:"application-areas-and-course-case-studies",level:2},{value:"Simulasyon ng Hamiltonian",id:"hamiltonian-simulation",level:3},{value:"Optimisasyon",id:"optimization",level:3},{value:"Quantum machine learning",id:"quantum-machine-learning",level:3},{value:"Mga partial differential equation",id:"partial-differential-equations",level:3},{value:"Konklusyon",id:"conclusion",level:2}];function u(a){const n={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...a.components};return(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Panimula sa praktikal na near-term quantum computing"})}),"\n",(0,t.jsx)(n.p,{children:"Mula nang unang imungkahi ang mga quantum computer mahigit apat na dekada na ang nakalipas, ang tanong ay: Hanggang saan kayang palawakin ng bagong pamamaraang ito ang mga limitasyon ng computation? Nagbigay sa atin ang theoretical computer science ng mga kapana-panabik na sagot. Kaya ng mga quantum computer na mag-factor ng malalaking integer nang mas mabilis kaysa sa pinakakilalang classical na pamamaraan, pabilisin ang unstructured search, at mas natural na i-simulate ang mga quantum system. Gayunpaman, marami sa mga ideyang ito ay nag-assume ng isang hinaharap na malakihan at fault-tolerant na quantum computer."}),"\n",(0,t.jsx)(n.p,{children:"Hindi pa naaabot ng teknolohiya ang lahat ng teoretikal na layuning iyon, pero mabilis itong bumubuti. Magagamit na ngayon ng mga mananaliksik ang mga quantum processor para tuklasin ang mga totoong problemang pang-agham at pang-industriya. Sa kursong ito, magkakaroon tayo ng hands-on na karanasan sa ilan sa mga pinakamapagpapangakong aplikasyon. Tatantyahin natin ang mga low-energy na katangian ng isang komplikadong molecular model, ie-simulate ang dynamics ng isang lattice gauge theory, at tutuklasin kung paano maimamapa ang isang financial portfolio problem sa isang quantum computer. Titingnan din natin ang mga mas bagong larangan kung saan nagsisimula pa lang nating maunawaan ang maaaring ialok ng mga quantum computer, kabilang ang quantum machine learning (QML) at mga quantum na pamamaraan para sa partial differential equations (PDEs)."}),"\n",(0,t.jsx)(n.p,{children:"Marami sa mga halimbawa sa kursong ito ay sapat na maliit para malutas ng isang classical computer. Sinadya iyon. Layunin nitong bigyan ka ng konkretong karanasan sa buong proseso ng paggamit ng quantum computer para tugunan ang isang real-world na problema. Ang ilang halimbawa ay kumakatawan sa mga problemang maaaring magkaroon ng quantum advantage sa mas malalaking sukat. Sa ibang mga halimbawa, gumagamit tayo ng pinasimpleng pamamaraan para hindi matakpan ng mga detalye ng implementasyon ang sentral na quantum na ideya."}),"\n",(0,t.jsx)(n.p,{children:"Pagsapit ng katapusan ng kurso, dapat ay mayroon ka nang pangkalahatang-ideya ng mga pangunahing quantum na aplikasyon at intuwisyon kung bakit maaaring maging kapaki-pakinabang ang mga quantum computer sa mga partikular na larangan. Makikilala mo ang mga karaniwang technique sa pagrepresenta ng mga problema sa mga quantum computer, matututunan kung paano nagtutulungan ang mga quantum at classical na pamamaraan, at sisimulan mong kilalanin kung aling mga tool at tradeoff ang mahalaga sa iba't ibang uri ng problema."}),"\n",(0,t.jsx)(n.p,{children:"Sa unang lesson na ito, tatalakayin natin ang ilang pangunahing konsepto at terminolohiya na tumutulong sa iyong maunawaan ang mga aplikasyon ng quantum computing sa mataas na antas, at bibigyan ka ng pangkalahatang-ideya ng mga pangunahing larangan ng aplikasyon na aktibong tinutugis ng siyentipikong komunidad."}),"\n",(0,t.jsx)(n.h2,{id:"what-quantum-computers-might-be-useful-for",children:"Kung saan maaaring maging kapaki-pakinabang ang mga quantum computer"}),"\n",(0,t.jsx)(n.p,{children:"Madalas na inilalarawan ang mga quantum computer bilang katunggali ng mga classical computer, pero mas angkop silang isipin bilang mga espesyalisadong resource sa loob ng mas malalaking classical na workflow. Ang mahalagang tanong, kung gayon, ay kung aling mga bahagi ng isang computation ang lalong angkop sa quantum hardware. Ang pinakamadaling sagot ay mula sa mga problemang quantum na mismo, tulad ng pag-uugali ng mga molecule, materyales, at quantum field. Direktang nirerepresenta at minamanipula ng isang quantum processor ang mga quantum state, habang ang mga resource na kailangan para sa pangkalahatang classical na paglalarawan ay lumalaki nang exponential kasabay ng laki ng system."}),"\n",(0,t.jsx)(n.p,{children:"Mas masalimuot ang kaso para sa mga problemang may classical na input at output, pero may mga magandang dahilan pa rin para tuklasin ang mga ito. Laganap at mahalaga sa ekonomiya ang mga optimization problem, kaya kahit katamtamang pagbuti sa kalidad ng solusyon o runtime ay maaaring may halaga. Maaari ring mag-alok ang mga quantum algorithm ng mga bagong paraan para galugarin ang mga komplikadong solution space o pakinabangan ang estruktura sa mga partikular na klase ng problema. May matibay na teoretikal na motibasyon ang quantum machine learning para sa ilang problemang may classical na input, kabilang ang structured classification at pagproseso ng napakalalaking dataset. Gayunpaman, bukas pa ring tanong kung maisasalin ang mga resultang ito sa praktikal na advantage sa totoong classical na data. Inilalarawan ng partial differential equations ang maraming mahahalagang system sa agham, inhinyeriya, at pananalapi, at maaaring mapabuti ng mga quantum algorithm ang scaling ng ilang high-dimensional na simulation at malalaking linear-algebra na problema."}),"\n",(0,t.jsx)(n.p,{children:"Sa lahat ng tatlong larangang ito, gayunpaman, maaaring mas malaki ang gastos sa paghahanda ng classical na input, pagpapatakbo ng quantum computation, at pagkuha ng kapaki-pakinabang na classical na sagot kaysa sa benepisyo ng quantum na hakbang. Isasaisip natin ang mga praktikal na hamong ito habang tinutuklas natin kung paano inilalapat ang mga quantum na pamamaraan sa bawat larangan."}),"\n",(0,t.jsx)(n.h2,{id:"near-term-quantum-utility-and-advantage",children:"Near-term na quantum utility at advantage"}),"\n",(0,t.jsx)(n.p,{children:"Hindi partikular na tungkol sa quantum advantage ang kursong ito, pero hindi maiiwasang pag-usapan ito. Ang pangunahing motibasyon sa likod ng mga quantum na aplikasyon ay gamitin ang mga quantum resource para palawakin ang kayang gawin ng mga classical computer nang mag-isa: makabuo ng mas tumpak na resulta, makarating sa mga solusyon nang mas mabilis, o lutasin ang mga problemang hindi maabot kung hindi. Ang mga sumusunod na magkakaugnay na termino ay tumutulong sa atin na malinaw na talakayin ang progresong nakikita natin:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantum speedup:"})," Habang lumalaki ang problema, mas paborable ang pag-scale ng oras na kailangan ng isang quantum na pamamaraan kumpara sa pinakamahusay na kaugnay na classical na pamamaraan para sa parehong gawain."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantum advantage:"})," Nahihigitan ng isang quantum-enabled na computation ang pinakamahusay na kaugnay na classical na pamamaraan sa isang malinaw na tinukoy na gawain at makabuluhang metric. Sa halip na isang solong at permanenteng milestone, ang quantum advantage ay isang umuunlad na hangganan na gumagalaw habang bumubuti ang parehong quantum at classical na pamamaraan."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantum utility:"})," Nag-aambag ang isang quantum computation sa isang kapaki-pakinabang na siyentipiko o teknikal na resulta. Gumagana ito sa sukat, lalim, at katumpakang lampas sa praktikal na brute-force na classical simulation, nang hindi kinakailangang higitan ang pinakamahusay na classical na pamamaraan."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Near-term algorithm:"})," Isang algorithm na dinisenyo para sa kasalukuyang mga quantum processor, na gumagamit ng limitadong circuit depth at madalas na umaasa sa classical post-processing at error mitigation sa halip na ganap na quantum error correction."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Fault-tolerant quantum computing:"})," Sa hinaharap, gagamit ang quantum computing ng quantum error correction para protektahan ang mga logical qubit sa buong computation. Kapag mas mababa ang mga physical error rate kaysa sa fault-tolerance threshold, kayang pigilan ng karagdagang resource sa error-correction ang mga logical error hanggang sa antas na kailangan ng mahahaba at maaasahang computation. Ginagawang posible ng fault tolerance ang mas malalalim na algorithm, kabilang ang malakihang implementasyon ng algorithm ni Shor."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Early fault tolerance:"})," Ang ibig sabihin ng fault tolerance ay napipigilan ang mga error, hindi lubusang naaalis. Sa mga maagang fault-tolerant na system, kailangan pa ring isaalang-alang ang natitirang logical error, at limitado pa rin ang lalim ng mga maaasahang circuit."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Heuristic algorithm:"})," Isang pamamaraang dinisenyo para makahanap ng mahusay na solusyon sa praktika nang hindi ginagarantiya ang pinakamainam na sagot o isang partikular na runtime."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"a-brief-foundation-in-complexity-theory",children:"Maikling pundasyon sa complexity theory"}),"\n",(0,t.jsx)(n.p,{children:"Sa ilang larangan ng aplikasyon, mayroon tayong matibay na teoretikal na dahilan para asahang maaaring magkaroon ng advantage ang isang quantum computer. Para maunawaan kung saan nanggagaling ang kumpiyansang ito, kailangan natin ng kaunting bokabularyo mula sa complexity theory."}),"\n",(0,t.jsx)(n.p,{children:"Pinag-aaralan ng complexity theory kung paano lumalaki ang mga resource na kailangan para lutasin ang isang problema habang lumalaki ang problema. Nagbibigay ito sa atin ng kapaki-pakinabang na mapa kung saan maaaring posible ang quantum speedup. Ilang termino ang lalong mahalaga sa kursong ito:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"P:"})," Mga problemang kayang lutasin nang mahusay ng isang classical computer, ibig sabihin ay polynomial ang paglaki ng mga kinakailangang resource kaugnay ng laki ng problema."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP:"})," Mga problemang kayang suriin nang mahusay ang isang iminungkahing solusyon, kahit na maaaring napakahirap hanapin ang solusyong iyon."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP-hard:"})," Mga problemang kasing-hirap man lang ng bawat problema sa NP. Ang isang NP-hard na problema ay hindi kinakailangang kabilang sa NP. Maraming optimization problem ang NP-hard."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP-complete:"})," Mga problemang parehong NP-hard at nasa NP. Ito ang pinakamahihirap na decision problem sa loob ng NP."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"BQP:"})," Mga problemang kayang lutasin nang mahusay ng isang quantum computer na may bounded na probabilidad ng error."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"May ilang kilalang ugnayan sa pagitan ng mga kategoryang ito. Nasa loob ng parehong NP at BQP ang P dahil ang problemang kayang lutasin nang mahusay sa isang classical computer ay kaya ring suriin nang classical at lutasin sa isang quantum computer. May iba pang ugnayang bukas pa rin. Hindi natin alam kung ang P ay katumbas ng NP o kung ang NP ay nasa loob ng BQP. Gayunpaman, karaniwang naniniwala ang mga mananaliksik na mas maliit ang P kaysa sa parehong NP at BQP, at na hindi kayang lutasin nang mahusay ng mga quantum computer ang bawat NP-complete na problema. Sa simpleng salita, ang isang quantum computer ay hindi mahiwagang kahon na agad na lumulutas ng bawat mahirap na problema."}),"\n",(0,t.jsx)(n.p,{children:"Ang pinakamatitibay na argumentong nakabatay sa complexity para sa quantum computing ay para sa mga partikular na uri ng problema. Mas mahusay nang husto ang pag-scale ng algorithm ni Shor kaysa sa pinakakilalang classical na algorithm para sa factoring at discrete logarithm, bagaman hindi pa napatunayang nasa labas ng P ang factoring. May matibay ding teoretikal na pundasyon ang pangkalahatang quantum simulation. Ang ilang quantum-simulation na problema ay BQP-complete, ibig sabihin ang mahusay na paglutas sa mga ito nang classical ay katumbas ng mahusay na pag-simulate sa anumang quantum computation. Lubhang malabong mangyari ang ganoong mahusay na classical simulation, na isa sa mga dahilan kung bakit itinuturing na napakapromising na larangan ng aplikasyon ang quantum Hamiltonian simulation."}),"\n",(0,t.jsx)(n.p,{children:"Ang ilang high-dimensional na PDE ay maaaring gawing BQP-complete na linear-system na problema, na nagbibigay sa atin ng matibay na dahilan para asahan ang quantum speedup kapag mahusay na mahahawakan ang mga input at output. May katulad na mga halimbawa ang QML: ang ilang gawaing may kinalaman sa quantum data ay BQP-complete, at ang ilang quantum model ay kayang bumuo ng mga sample na mahirap gayahin nang classical."}),"\n",(0,t.jsx)(n.p,{children:"Hindi gaanong tuwiran ang kaso para sa optimization. Hindi inaasahang malulutas nang mahusay ng mga quantum computer ang mga arbitraryong NP-hard na problema, pero maaari pa rin silang makatulong sa mga structured na problema, partikular na instance, o tiyak na hakbang sa isang optimization workflow. Halimbawa, nagbibigay ang algorithm ni Grover ng quadratic speedup para sa unstructured search. Makabuluhang pagbuti iyon, kahit na ang square root ng isang napakalaking search space ay maaari pa ring maging napakalaki."}),"\n",(0,t.jsx)(n.h2,{id:"from-complexity-theory-to-practical-evidence",children:"Mula sa complexity theory tungo sa praktikal na ebidensya"}),"\n",(0,t.jsx)(n.p,{children:"Masasabi sa atin ng complexity theory kung saan maaaring posible ang quantum speedup, pero kadalasan ay hindi nito masasabi kung paano gumaganap ang isang pamamaraan sa isang partikular na problema o partikular na quantum computer. Marami sa mga pamamaraang ginagamit sa kasalukuyang hardware ay heuristic. Dinisenyo ang mga ito para makahanap ng mahusay na sagot sa praktika, pero hindi nila ginagarantiya ang pinakamainam na sagot o isang partikular na runtime."}),"\n",(0,t.jsx)(n.p,{children:"Hindi natatangi sa quantum computing ang mga heuristic, at ang pagtawag sa isang pamamaraan na heuristic ay hindi nangangahulugang hindi ito maaasahan o hindi siyentipiko. Malaki ang pag-asa ng classical optimization, machine learning, at computational chemistry sa mga heuristic kapag masyadong magastos ang eksaktong solusyon. Maaaring mag-alok ang isang quantum heuristic ng bagong paraan para galugarin ang solution space, maghanda ng mga kapaki-pakinabang na state, o tukuyin ang mga promising na kandidato. Isang empirikal na tanong kung gumagana ito nang mahusay: kailangan natin itong patakbuhin at sukatin ang resulta."}),"\n",(0,t.jsx)(n.p,{children:"Dahil walang kasamang garantiya sa performance ang mga heuristic, sinusuri natin ang mga ito gamit ang malinaw na success metric, matitibay na classical baseline, at mga test sa iba't ibang laki ng problema. Nakakatulong ito para makita natin kung saan mahusay gumagana ang isang pamamaraan at kung paano nagbabago ang performance nito habang lumalaki ang problema."}),"\n",(0,t.jsx)(n.h2,{id:"application-areas-and-course-case-studies",children:"Mga larangan ng aplikasyon at mga case study ng kurso"}),"\n",(0,t.jsx)(n.p,{children:"Inaayos natin ang kurso sa paligid ng apat na malawak na larangan ng aplikasyon. Hindi nila sinasaklaw ang bawat posibleng gamit ng isang quantum computer, pero nagbibigay sila sa atin ng kapaki-pakinabang na paraan para ihambing kung saan nakatayo ang pinakamatitibay na argumento at kung nasaan ang mga bukas na tanong."}),"\n",(0,t.jsx)(n.h3,{id:"hamiltonian-simulation",children:"Simulasyon ng Hamiltonian"}),"\n",(0,t.jsx)(n.p,{children:"Kasama sa Hamiltonian simulation ang pagtantya ng mga energy, pag-aaral ng mga katangiang kemikal at ng materyales, at pagmomodelo kung paano nagbabago sa paglipas ng panahon ang mga quantum system. Sumasaklaw ito sa chemistry, materials science, condensed-matter physics, at high-energy at nuclear physics. Sinusuri ng ating mga case study ang isang strongly correlated na iron-sulfur model gamit ang sample-based quantum diagonalization at sini-simulate ang dynamics ng hadron gamit ang symmetry-aware na lattice representation. Dalawa lang ito sa maraming halimbawa mula sa mas malaking larangan, na kinabibilangan din ng mga reaction mechanism, magnetic na materyales, at iba pang many-body dynamics."}),"\n",(0,t.jsx)(n.h3,{id:"optimization",children:"Optimisasyon"}),"\n",(0,t.jsx)(n.p,{children:"Lumilitaw ang optimization saanman mula sa pananalapi at logistics hanggang sa scheduling at mga energy system. Isa rin itong larangan kung saan mahirap itatag ang advantage, dahil napakahusay ng mga classical solver at maaaring magdagdag ng magastos na overhead ang mga quantum mapping. Gumagamit ang ating case study ng portfolio selection para tuklasin kung paano nirerepresenta, pinapatakbo, at bina-benchmark ang isang optimization problem nang hindi ina-assume na awtomatikong mahahanap ng quantum computer ang eksaktong optimum."}),"\n",(0,t.jsx)(n.h3,{id:"quantum-machine-learning",children:"Quantum machine learning"}),"\n",(0,t.jsx)(n.p,{children:"Tinatanong ng quantum machine learning kung mapapabuti ng mga quantum circuit o quantum data ang isang gawain sa pagkatuto. Kabilang sa mahahalagang tanong ang data encoding, gastos sa training, generalization, at paghahambing sa matitibay na classical model."}),"\n",(0,t.jsx)(n.h3,{id:"partial-differential-equations",children:"Mga partial differential equation"}),"\n",(0,t.jsx)(n.p,{children:"Inilalarawan ng partial differential equations ang mga system tulad ng mga fluid, init, at alon. Maaaring pabilisin ng mga quantum algorithm ang mga bahagi ng ilang PDE workflow, pero maaaring malaking gastos ang paghahanda ng data at pagkuha ng kapaki-pakinabang na classical na sagot. Binubuo pa ang partikular na case study."}),"\n",(0,t.jsx)(n.p,{children:"Sa mga susunod na lesson, itatanong natin ang parehong pangunahing mga tanong sa bawat larangan: Ano ang problema, bakit maaaring makatulong ang quantum computing, ano ang mga limitasyon, at ano talaga ang ipinapakita ng ebidensya? Magsisimula tayo sa Hamiltonian simulation, kung saan quantum na mismo ang problema."}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Konklusyon"}),"\n",(0,t.jsx)(n.p,{children:"Marami na tayong nasaklaw, pero simple ang pangunahing ideya: ang mga quantum computer ay mga espesyalisadong tool, at nakasalalay ang halaga nila sa paggamit ng tamang quantum na pamamaraan para sa tamang problema o bahagi ng mas malaking problema. Ang Hamiltonian simulation ang may pinakamalinaw na teoretikal na pundasyon, ang optimization ay may mature na hanay ng mga heuristic na pamamaraan at benchmark, at ang QML at PDEs ay nag-aalok ng mga promising na direksyong patuloy pang umuunlad."}),"\n",(0,t.jsx)(n.p,{children:"Sa mga susunod na lesson, lilipat tayo mula sa malawak na pangkalahatang-ideyang ito tungo sa mga hands-on na halimbawa. Para sa bawat aplikasyon, itatanong natin kung anong problema ang sinusubukan nating lutasin, anong papel ang ginagampanan ng quantum computer, paano binibigyang-kahulugan ang resulta, at ano ang matututunan natin mula rito. Layunin nitong buuin ang iyong intuwisyon kung saan maaaring makatulong ang quantum computing at kung ano ang kailangan para gawing totoong computation ang isang promising na ideya."}),"\n"]})}function e(a={}){const{wrapper:n}={...(0,s.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(u,{...a})}):u(a)}},28453(a,n,i){i.d(n,{R:()=>m,x:()=>l});var g=i(96540);const t={},s=g.createContext(t);function m(a){const n=g.useContext(s);return g.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function l(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:m(a.components),g.createElement(s.Provider,{value:n},a.children)}}}]);